"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { FormEvent, ReactNode, useMemo, useState } from "react";
import { AlertTriangle, Download, RefreshCcw, Search } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useConfirmationDialog } from "@/components/ui/confirmation-dialog";
import { clearDomainResource, useDomainResource } from "@/lib/domain-resource";
import { domainApi, formatDomainAmount, formatDomainDate } from "@/lib/domain-api";
import { AdminPricingPage } from "./admin-pricing-page";
import { AdminSettingsPage } from "./admin-settings-page";

export type AdminSection = "Vendors" | "Domains" | "Orders" | "Pricing" | "Reports" | "Settings" | "Operations" | "Notifications";
type PageResult<T> = { items: T[]; total: number; page: number; limit: number; pages: number };
type VendorRow = { vendorId: string; name: string; email: string; accountActive: boolean; domains: number; activeDomains: number; orders: number; pendingOrders: number; totalSpent: number; currency: string; lastActivityAt?: string };
type DomainRow = { _id: string; domainName: string; vendorId: string; vendorName?: string; vendorEmail?: string; status: unknown; expirationDate?: string; renewalMode?: string; lockStatus?: boolean };
type OrderRow = { orderId: string; domainName: string; vendorId: string; vendorName?: string; vendorEmail?: string; operation: string; period: number; amount: number; currency: string; status: string; financialStatus?: string; createdAt: string; pricingSnapshot?: { providerCostCustomerCurrency?: number; marginAmount?: number } };
type LedgerRow = { _id: string; orderId: string; vendorId: string; vendorName?: string; vendorEmail?: string; operation: string; status: string; credits: number; balanceAfter: number; createdAt: string };
type AuditRow = { _id: string; action: string; actorRole: string; vendorId: string; vendorName: string; vendorEmail: string; domainName: string; outcome: string; createdAt: string };
type FinancialRow = { count: number; revenue: number; estimatedProviderCost: number; profit: number | null; missingCostOrders: number; confirmedProviderCost?: number | null; confirmedProfit?: number | null; unconfirmedChargeOrders?: number };
type ProviderChargeRow = { orderId: string; vendorId: string; vendorName: string; vendorEmail: string; domainName: string; operation: string; vendorCharge: number; currency: string; estimatedProviderCost: number | null; originalProviderCharge: number | null; originalProviderChargeCurrency: string; confirmedProviderCharge: number | null; providerRefund: number; netProviderCost: number | null; confirmedProfit: number | null; costDifference: number | null; financialStatus: string; reviewReason: string; traceId: string; confirmedAt?: string; completedAt: string };
type OrderIssueRow = { orderId: string; domainName: string; vendorId: string; vendorName?: string; vendorEmail?: string; operation: string; amount: number; currency: string; status: string; failureMessage?: string; financialReviewReason?: string; createdAt: string };
type ProviderTransactionRow = { _id: string; providerEntryKey: string; orderId: string; vendorId: string; vendorName?: string; vendorEmail?: string; domainName: string; operation: string; chargeType: "ADD" | "SUBTRACT"; providerStatus: string; matchStatus: string; amount: number; currency: string; bookedCustomerAmount?: number | null; customerCurrency?: string; exchangeAmount?: number | null; exchangeCurrency?: string; exchangeRate?: number | null; exchangeRateSource?: string; traceId?: string; productId?: string; description?: string; oldBalance?: number | null; balance?: number | null; providerCreatedAt: string; confirmedAt?: string };
type AdminNotification = { _id: string; type: string; severity: "INFO" | "WARNING" | "CRITICAL"; title: string; message: string; orderId?: string; domainName?: string; readAt?: string | null; createdAt: string };
type Report = {
  range: { from: string; to: string; groupBy: "day" | "month" | "year"; timezone: string };
  summary: { completedOrders: number; registrations: number; renewals: number; transfers: number; restores: number; revenue: number; estimatedProviderCost: number | null; estimatedCostKnownOrders: number; actualProviderCharge: number | null; providerRefunds: number | null; netProviderCost: number | null; actualChargeConfirmedOrders: number; confirmedProfit: number | null; profit: number | null; profitMarginPercent: number | null; averageOrderValue: number; currency: string };
  operations: Array<FinancialRow & { operation: string }>;
  statuses: Array<{ status: string; count: number }>;
  trend: Array<FinancialRow & { period: string; registrations: number; renewals: number }>;
  domainTypes: Array<FinancialRow & { tld: string }>;
  vendors: Array<FinancialRow & { vendorId: string; vendorName: string; vendorEmail: string; registrations: number; renewals: number; lastCompletedAt?: string }>;
  providerCharges: Array<{ orderId: string; domainName: string; operation: string; completedAt: string; estimatedProviderCost: number | null; actualProviderCharge: number | null; actualProviderChargeCurrency: string; actualProviderChargeConfirmedAt?: string; providerTransactionId: string; costDifference: number | null }>;
  issues: Array<{ orderId: string; domainName: string; vendorName?: string; vendorEmail?: string; operation: string; amount: number; currency: string; status: string; failureMessage?: string; createdAt: string }>;
};

function PageError({ message, retry }: { message: string; retry: () => void }) { return <Card><CardContent className="flex items-center justify-between gap-4 py-6"><div className="flex items-center gap-3"><AlertTriangle className="size-5 text-destructive" /><div><p className="font-medium">Unable to load this section</p><p className="text-sm text-muted-foreground">{message}</p></div></div><Button variant="outline" onClick={retry}><RefreshCcw />Retry</Button></CardContent></Card>; }
const Loading = () => <Card><CardContent className="py-12 text-center text-sm text-muted-foreground">Loading domain information...</CardContent></Card>;
const Empty = ({ children }: { children: ReactNode }) => <div className="py-12 text-center text-sm text-muted-foreground">{children}</div>;

function Pager({ page, pages, total, setPage }: { page: number; pages: number; total: number; setPage: (page: number) => void }) {
  return <div className="flex items-center justify-between border-t pt-4"><p className="text-sm text-muted-foreground">{total.toLocaleString("en-IN")} results · Page {page} of {Math.max(pages, 1)}</p><div className="flex gap-2"><Button variant="outline" size="sm" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</Button><Button variant="outline" size="sm" disabled={page >= pages} onClick={() => setPage(page + 1)}>Next</Button></div></div>;
}

function SearchHeader({ title, description, value, setValue, submit, refresh }: { title: string; description: string; value: string; setValue: (value: string) => void; submit: (event: FormEvent) => void; refresh: () => void }) {
  return <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><h2 className="text-2xl font-semibold tracking-tight">{title}</h2><p className="text-sm text-muted-foreground">{description}</p></div><form onSubmit={submit} className="flex w-full gap-2 md:max-w-md"><Input value={value} onChange={(event) => setValue(event.target.value)} placeholder={`Search ${title.toLowerCase()}`} /><Button><Search />Search</Button><Button type="button" variant="outline" size="icon" aria-label="Refresh" onClick={refresh}><RefreshCcw /></Button></form></div>;
}

function VendorsPage({ token }: { token: string }) {
  const [input, setInput] = useState(""); const [filter, setFilter] = useState(""); const [page, setPage] = useState(1);
  const resource = useDomainResource<PageResult<VendorRow>>(token, `/v1/admin/domain/vendors?page=${page}&limit=25&filter=${encodeURIComponent(filter)}`, 20_000);
  return <div className="space-y-6"><SearchHeader title="Vendors" description="View domain usage, orders and account activity for each vendor." value={input} setValue={setInput} submit={(event) => { event.preventDefault(); setPage(1); setFilter(input.trim()); }} refresh={resource.reload} />{resource.error ? <PageError message={resource.error} retry={resource.reload} /> : resource.loading ? <Loading /> : <Card><CardHeader><CardTitle>Domain vendors</CardTitle><CardDescription>Select a vendor to see their domains, orders and credit activity.</CardDescription></CardHeader><CardContent className="space-y-4 overflow-x-auto"><table className="w-full min-w-5xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Vendor</th><th>Domains</th><th>Orders</th><th>Pending</th><th>Spend</th><th>Last activity</th><th className="text-right">Account</th></tr></thead><tbody>{resource.data?.items.map((item) => <tr key={item.vendorId} className="border-b"><td className="py-4"><Link className="font-medium hover:underline" href={`/admin/vendors/${item.vendorId}`}>{item.name}</Link><p className="text-xs text-muted-foreground">{item.email || item.vendorId}</p></td><td>{item.activeDomains} / {item.domains}</td><td>{item.orders}</td><td>{item.pendingOrders}</td><td>{formatDomainAmount(item.totalSpent, item.currency)}</td><td>{formatDomainDate(item.lastActivityAt)}</td><td className="text-right"><Badge variant={item.accountActive ? "secondary" : "outline"}>{item.accountActive ? "Active" : "Inactive"}</Badge></td></tr>)}</tbody></table>{!resource.data?.items.length ? <Empty>No vendors match your search.</Empty> : <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}</CardContent></Card>}</div>;
}

function DomainsPage({ token }: { token: string }) {
  const [input, setInput] = useState(""); const [filter, setFilter] = useState(""); const [page, setPage] = useState(1); const [expiry, setExpiry] = useState("");
  const resource = useDomainResource<PageResult<DomainRow>>(token, `/v1/admin/domain/domains?page=${page}&limit=25&filter=${encodeURIComponent(filter)}${expiry ? `&expiry=${expiry}` : ""}`, 15_000);
  return <div className="space-y-6"><SearchHeader title="Domains" description="Monitor domain status, renewal mode, expiry and security." value={input} setValue={setInput} submit={(event) => { event.preventDefault(); setPage(1); setFilter(input.trim()); }} refresh={resource.reload} /><div className="flex justify-end"><select className="h-9 rounded-md border bg-background px-3 text-sm" value={expiry} onChange={(event) => { setPage(1); setExpiry(event.target.value); }}><option value="">All expiry dates</option><option value="30">Next 30 days</option><option value="60">Next 60 days</option><option value="90">Next 90 days</option><option value="expired">Expired</option></select></div>{resource.error ? <PageError message={resource.error} retry={resource.reload} /> : resource.loading ? <Loading /> : <Card><CardHeader><CardTitle>Registered domains</CardTitle><CardDescription>Select a domain for complete lifecycle and order history.</CardDescription></CardHeader><CardContent className="space-y-4 overflow-x-auto"><table className="w-full min-w-4xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Domain</th><th>Vendor</th><th>Status</th><th>Renewal</th><th>Expires</th><th className="text-right">Security</th></tr></thead><tbody>{resource.data?.items.map((item) => <tr key={item._id || item.domainName} className="border-b"><td className="py-4"><Link className="font-medium hover:underline" href={`/admin/domains/${encodeURIComponent(item.domainName)}`}>{item.domainName}</Link></td><td><VendorIdentity item={item} /></td><td><Badge variant="outline">{String(item.status || "Unknown")}</Badge></td><td>{item.renewalMode || "Not available"}</td><td>{formatDomainDate(item.expirationDate)}</td><td className="text-right">{item.lockStatus == null ? "Not available" : item.lockStatus ? "Locked" : "Unlocked"}</td></tr>)}</tbody></table>{!resource.data?.items.length ? <Empty>No domains match these filters.</Empty> : <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}</CardContent></Card>}</div>;
}

function OrdersPage({ token }: { token: string }) {
  const requestConfirmation = useConfirmationDialog();
  const [page, setPage] = useState(1); const [status, setStatus] = useState(""); const [operation, setOperation] = useState(""); const [pending, setPending] = useState(""); const [message, setMessage] = useState("");
  const resource = useDomainResource<PageResult<OrderRow>>(token, `/v1/admin/domain/orders?page=${page}&limit=25${status ? `&status=${status}` : ""}${operation ? `&operation=${operation}` : ""}`, 10_000);
  const act = async (order: OrderRow, action: "reconcile" | "release-reservation") => { if (action === "release-reservation" && !await requestConfirmation({ title: "Release reserved credits?", description: `Release the reserved credits for ${order.domainName} only after confirming that the domain operation was not completed.`, confirmLabel: "Release Credits", destructive: true })) return; setPending(order.orderId + action); setMessage(""); try { await domainApi(token, `/v1/admin/domain/orders/${order.orderId}/${action}`, { method: "POST" }); clearDomainResource("/v1/admin/domain/"); resource.reload(); setMessage("Order updated successfully."); } catch (error) { setMessage(error instanceof Error ? error.message : "The order could not be updated."); } finally { setPending(""); } };
  return <div className="space-y-6"><div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><h2 className="text-2xl font-semibold">Orders</h2><p className="text-sm text-muted-foreground">Review registrations, renewals, transfers and recoveries.</p></div><div className="flex gap-2"><select className="h-9 rounded-md border bg-background px-3 text-sm" value={operation} onChange={(e) => { setPage(1); setOperation(e.target.value); }}><option value="">All operations</option>{["REGISTER", "RENEW", "TRANSFER", "RESTORE"].map((v) => <option key={v}>{v}</option>)}</select><select className="h-9 rounded-md border bg-background px-3 text-sm" value={status} onChange={(e) => { setPage(1); setStatus(e.target.value); }}><option value="">All statuses</option>{["COMPLETED", "FAILED", "PROVIDER_PENDING", "RECONCILIATION_REQUIRED", "RESERVED", "RESERVING", "CREATED"].map((v) => <option key={v}>{v}</option>)}</select><Button variant="outline" size="icon" onClick={resource.reload}><RefreshCcw /></Button></div></div>{message && <p className="rounded-md border p-3 text-sm">{message}</p>}{resource.error ? <PageError message={resource.error} retry={resource.reload} /> : resource.loading ? <Loading /> : <Card><CardHeader><CardTitle>Domain orders</CardTitle><CardDescription>Open an order for pricing, credit and processing details.</CardDescription></CardHeader><CardContent className="space-y-4 overflow-x-auto"><table className="w-full min-w-7xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Domain</th><th>Vendor</th><th>Type</th><th>Cost</th><th>Vendor price</th><th>Margin</th><th>Created</th><th>Status</th><th className="text-right">Action</th></tr></thead><tbody>{resource.data?.items.map((item) => <tr key={item.orderId} className="border-b"><td className="py-4"><Link className="font-medium hover:underline" href={`/admin/orders/${item.orderId}`}>{item.domainName}</Link></td><td><VendorIdentity item={item} /></td><td>{item.operation}</td><td>{formatDomainAmount(item.pricingSnapshot?.providerCostCustomerCurrency, item.currency)}</td><td>{formatDomainAmount(item.amount, item.currency)}</td><td>{formatDomainAmount(item.pricingSnapshot?.marginAmount, item.currency)}</td><td>{formatDomainDate(item.createdAt)}</td><td><Badge variant={item.status === "COMPLETED" ? "secondary" : "outline"}>{item.status.replaceAll("_", " ")}</Badge></td><td className="text-right"><div className="flex justify-end gap-2">{["RESERVING", "RESERVED", "PROVIDER_PENDING", "RECONCILIATION_REQUIRED"].includes(item.status) && <Button size="sm" variant="outline" disabled={Boolean(pending)} onClick={() => void act(item, "reconcile")}>Check status</Button>}{item.status === "RECONCILIATION_REQUIRED" && <Button size="sm" variant="destructive" disabled={Boolean(pending)} onClick={() => void act(item, "release-reservation")}>Release credits</Button>}</div></td></tr>)}</tbody></table>{!resource.data?.items.length ? <Empty>No orders match these filters.</Empty> : <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}</CardContent></Card>}</div>;
}

function SimpleRows({ title, items, keyName }: { title: string; items: Array<Record<string, unknown>>; keyName: string }) { return <Card><CardHeader><CardTitle>{title}</CardTitle></CardHeader><CardContent className="space-y-2">{items?.map((item, index) => <div key={String(item[keyName] || index)} className="grid gap-2 rounded-md border p-3 text-sm md:grid-cols-4">{Object.entries(item).filter(([key]) => ["domainName", "orderId", "operation", "status", "action", "outcome", "credits", "createdAt", "expirationDate"].includes(key)).slice(0, 4).map(([key, value]) => <div key={key}><p className="text-xs capitalize text-muted-foreground">{key.replace(/([A-Z])/g, " $1")}</p><p className="break-all">{key.endsWith("At") || key.endsWith("Date") ? formatDomainDate(String(value)) : String(value ?? "Not available").replaceAll("_", " ")}</p></div>)}</div>)}{!items?.length && <Empty>No recent activity.</Empty>}</CardContent></Card>; }

function VendorIdentity({ item }: { item: { vendorId?: string; vendorName?: string; vendorEmail?: string } }) {
  return <div><p className="font-medium">{item.vendorName || "Vendor"}</p><p className="text-xs text-muted-foreground">{item.vendorEmail || "Email not available"}</p></div>;
}

function ProviderTransactionsPage({ token }: { token: string }) {
  const [page, setPage] = useState(1); const [filter, setFilter] = useState(""); const [operation, setOperation] = useState(""); const [providerStatus, setProviderStatus] = useState(""); const [matchStatus, setMatchStatus] = useState(""); const [chargeType, setChargeType] = useState(""); const [currency, setCurrency] = useState(""); const [selected, setSelected] = useState<ProviderTransactionRow | null>(null);
  const query = `/v1/admin/domain/provider/transactions?page=${page}&limit=25&filter=${encodeURIComponent(filter)}${operation ? `&operation=${operation}` : ""}${providerStatus ? `&providerStatus=${providerStatus}` : ""}${matchStatus ? `&status=${matchStatus}` : ""}${chargeType ? `&chargeType=${chargeType}` : ""}${currency ? `&currency=${currency}` : ""}`;
  const resource = useDomainResource<PageResult<ProviderTransactionRow>>(token, query, 10_000);
  const change = (setter: (value: string) => void, value: string) => { setPage(1); setSelected(null); setter(value); };
  return <div className="space-y-6"><div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><h2 className="text-2xl font-semibold">Provider transactions</h2><p className="text-sm text-muted-foreground">Review the provider debit and refund records saved against domain orders.</p></div><Button type="button" variant="outline" onClick={resource.reload}><RefreshCcw />Refresh</Button></div><Card><CardHeader><CardTitle>Find a transaction</CardTitle><CardDescription>Filters are applied on the server, so only the current page is loaded.</CardDescription></CardHeader><CardContent className="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><Input value={filter} onChange={(event) => change(setFilter, event.target.value)} placeholder="Search domain, order, trace or product ID" /><select className="h-9 rounded-md border bg-background px-3 text-sm" value={operation} onChange={(event) => change(setOperation, event.target.value)}><option value="">All operations</option>{["REGISTER", "RENEW", "TRANSFER", "RESTORE", "REFUND", "OTHER"].map((value) => <option key={value}>{value}</option>)}</select><select className="h-9 rounded-md border bg-background px-3 text-sm" value={providerStatus} onChange={(event) => change(setProviderStatus, event.target.value)}><option value="">All provider results</option>{["SUCCESS", "FAILED", "CANCELED", "PROCESSING", "REFUNDED", "UNKNOWN"].map((value) => <option key={value}>{value}</option>)}</select><select className="h-9 rounded-md border bg-background px-3 text-sm" value={matchStatus} onChange={(event) => change(setMatchStatus, event.target.value)}><option value="">All matching results</option>{["UNMATCHED", "CONFIRMED", "MISMATCH", "NEEDS_REVIEW"].map((value) => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select><select className="h-9 rounded-md border bg-background px-3 text-sm" value={chargeType} onChange={(event) => change(setChargeType, event.target.value)}><option value="">Debits and refunds</option><option value="SUBTRACT">Provider debit</option><option value="ADD">Provider refund or credit</option></select><Input value={currency} maxLength={3} onChange={(event) => change(setCurrency, event.target.value.toUpperCase().replace(/[^A-Z]/g, ""))} placeholder="Currency, for example USD" /></CardContent></Card>{resource.error ? <PageError message={resource.error} retry={resource.reload} /> : resource.loading ? <Loading /> : <Card><CardHeader><CardTitle>Saved provider ledger</CardTitle><CardDescription>Select a row to inspect its identifiers, conversion and balance details.</CardDescription></CardHeader><CardContent className="space-y-4 overflow-x-auto"><table className="w-full min-w-7xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Domain</th><th>Vendor</th><th>Operation</th><th>Entry</th><th>Original amount</th><th>Booked amount</th><th>Provider result</th><th>Match</th><th>Provider date</th><th className="text-right">Details</th></tr></thead><tbody>{resource.data?.items.map((row) => <tr key={row.providerEntryKey} className="border-b"><td className="py-4 font-medium">{row.domainName || "Not linked"}</td><td><VendorIdentity item={row} /></td><td>{row.operation}</td><td>{row.chargeType === "SUBTRACT" ? "Debit" : "Refund / credit"}</td><td>{formatDomainAmount(row.amount, row.currency)}</td><td>{row.bookedCustomerAmount == null || !row.customerCurrency ? "Not available" : formatDomainAmount(row.bookedCustomerAmount, row.customerCurrency)}</td><td><Badge variant="outline">{row.providerStatus}</Badge></td><td><Badge variant="outline">{row.matchStatus.replaceAll("_", " ")}</Badge></td><td>{formatDomainDate(row.providerCreatedAt)}</td><td className="text-right"><Button type="button" size="sm" variant="outline" onClick={() => setSelected(row)}>View</Button></td></tr>)}</tbody></table>{!resource.data?.items.length && <Empty>No provider transactions match these filters.</Empty>}{resource.data && <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={(value) => { setPage(value); setSelected(null); }} />}</CardContent></Card>}{selected && <Card><CardHeader><CardTitle>Transaction details</CardTitle><CardDescription>Exact values stored from the provider ledger and the order-time conversion.</CardDescription></CardHeader><CardContent className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{[["Trace ID", selected.traceId || "Not provided"], ["Provider product ID", selected.productId || "Not provided"], ["Order ID", selected.orderId || "Not linked"], ["Description", selected.description || "Not provided"], ["Exchange value", selected.exchangeAmount == null || !selected.exchangeCurrency ? "Not provided" : formatDomainAmount(selected.exchangeAmount, selected.exchangeCurrency)], ["Conversion source", selected.exchangeRateSource?.replaceAll("_", " ") || "Not available"], ["Conversion rate", selected.exchangeRate ?? "Not available"], ["Previous provider balance", selected.oldBalance ?? "Not provided"], ["New provider balance", selected.balance ?? "Not provided"], ["Confirmed", formatDomainDate(selected.confirmedAt)]].map(([label, value]) => <div key={String(label)} className="rounded-md border p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="break-all font-medium">{String(value)}</p></div>)}{selected.orderId && <div className="flex items-end"><Button asChild variant="outline"><Link href={`/admin/orders/${selected.orderId}`}>Open Order</Link></Button></div>}</CardContent></Card>}</div>;
}

function RegistrationDetails({ details }: { details: any }) {
  if (!details) return <Card><CardHeader><CardTitle>Registration details</CardTitle><CardDescription>This order was created before registration snapshots were enabled, or it is not a registration order.</CardDescription></CardHeader></Card>;
  return <div className="space-y-6">
    <Card><CardHeader><CardTitle>Registration setup</CardTitle><CardDescription>Information captured when the vendor submitted this registration.</CardDescription></CardHeader><CardContent className="grid gap-4 md:grid-cols-2"><div><p className="text-xs text-muted-foreground">Nameservers</p><p className="font-medium">{details.nameServers?.join(", ") || "Not provided"}</p></div><div><p className="text-xs text-muted-foreground">Details captured</p><p className="font-medium">{formatDomainDate(details.capturedAt)}</p></div>{Object.entries(details.tldAttributes || {}).map(([key, value]) => <div key={key}><p className="text-xs capitalize text-muted-foreground">{key.replace(/([A-Z])/g, " $1")}</p><p className="font-medium">{String(value)}</p></div>)}</CardContent></Card>
    <Card><CardHeader><CardTitle>Registration contacts</CardTitle><CardDescription>Registrant, administrative, technical and billing contacts saved securely with this order.</CardDescription></CardHeader><CardContent className="grid gap-4 lg:grid-cols-2">{details.contacts?.map((contact: any, index: number) => <div key={`${contact.contactType}-${index}`} className="rounded-md border p-4"><div className="mb-3 flex items-center justify-between"><p className="font-semibold">{contact.contactType} contact</p><Badge variant="outline">{contact.country}</Badge></div><div className="grid gap-3 text-sm sm:grid-cols-2"><div><p className="text-xs text-muted-foreground">Name</p><p>{contact.firstName} {contact.lastName}</p></div><div><p className="text-xs text-muted-foreground">Company</p><p>{contact.companyName || "Not provided"}</p></div><div><p className="text-xs text-muted-foreground">Email</p><p className="break-all">{contact.eMail}</p></div><div><p className="text-xs text-muted-foreground">Phone</p><p>+{contact.phoneCountryCode} {contact.phone}</p></div><div className="sm:col-span-2"><p className="text-xs text-muted-foreground">Address</p><p>{[contact.address, contact.city, contact.state, contact.postalCode, contact.country].filter(Boolean).join(", ")}</p></div></div></div>)}{!details.contacts?.length && <Empty>No registration contacts were saved.</Empty>}</CardContent></Card>
  </div>;
}

function DetailPage({ token, kind, id }: { token: string; kind: "vendors" | "domains" | "orders"; id: string }) {
  const [financialMessage, setFinancialMessage] = useState("");
  const [financialPending, setFinancialPending] = useState(false);
  const resource = useDomainResource<Record<string, any>>(token, `/v1/admin/domain/${kind}/${encodeURIComponent(id)}`, 0);
  if (resource.error) return <PageError message={resource.error} retry={resource.reload} />; if (resource.loading || !resource.data) return <Loading />; const data = resource.data;
  if (kind === "vendors") return <div className="space-y-6"><Button asChild variant="ghost"><Link href="/admin/vendors">← Back to vendors</Link></Button><div><h2 className="text-2xl font-semibold">{data.vendor.name}</h2><p className="text-sm text-muted-foreground">{data.vendor.email || data.vendor.vendorId}</p></div><section className="grid gap-4 md:grid-cols-4">{[["Domains", data.domains.total], ["Active domains", data.domains.active], ["Pending orders", data.orders.pending], ["Total spend", formatDomainAmount(data.orders.spent, "INR")]].map(([label, value]) => <Card key={String(label)}><CardHeader><CardDescription>{label}</CardDescription><CardTitle>{value}</CardTitle></CardHeader></Card>)}</section><Card><CardContent className="grid gap-4 py-6 md:grid-cols-2">{[["Phone", data.vendor.phone || "Not provided"], ["Location", data.vendor.location || "Not provided"], ["Account", data.vendor.accountActive ? "Active" : "Inactive"], ["Verification", data.vendor.verified ? "Verified" : "Pending"]].map(([label, value]) => <div key={label}><p className="text-xs text-muted-foreground">{label}</p><p className="font-medium">{value}</p></div>)}</CardContent></Card><SimpleRows title="Recent domains" items={data.recentDomains} keyName="domainName" /><SimpleRows title="Recent orders" items={data.recentOrders} keyName="orderId" /></div>;
  if (kind === "domains") return <div className="space-y-6"><Button asChild variant="ghost"><Link href="/admin/domains">← Back to domains</Link></Button><div><h2 className="text-2xl font-semibold">{data.domain.domainName}</h2><p className="text-sm text-muted-foreground">Complete lifecycle, ownership and original registration information.</p></div><Card><CardContent className="grid gap-5 py-6 md:grid-cols-3"><div><p className="text-xs text-muted-foreground">Vendor</p><VendorIdentity item={data.domain} /></div>{[["Status", String(data.domain.status || "Unknown")], ["Expires", formatDomainDate(data.domain.expirationDate)], ["Renewal mode", data.domain.renewalMode || "Not available"], ["Security lock", data.domain.lockStatus ? "Locked" : "Unlocked"], ["Last checked", formatDomainDate(data.domain.lastProviderSyncAt)]].map(([label, value]) => <div key={label}><p className="text-xs text-muted-foreground">{label}</p><p className="font-medium">{value}</p></div>)}</CardContent></Card>{data.registration && <Card><CardHeader><CardTitle>Original registration</CardTitle></CardHeader><CardContent className="grid gap-4 md:grid-cols-4">{[["Order ID", data.registration.orderId], ["Purchased period", `${data.registration.period} year(s)`], ["Registered", formatDomainDate(data.registration.completedAt || data.registration.createdAt)], ["Order expiry", formatDomainDate(data.registration.expirationDate)]].map(([label, value]) => <div key={label}><p className="text-xs text-muted-foreground">{label}</p><p className="font-medium">{value}</p></div>)}</CardContent></Card>}<RegistrationDetails details={data.registration?.details} /><SimpleRows title="Related orders" items={data.orders} keyName="orderId" /><SimpleRows title="Recent activity" items={data.activity} keyName="_id" /></div>;
  const reconcileFinancialCharge = async () => {
    setFinancialPending(true); setFinancialMessage("");
    try {
      await domainApi(token, `/v1/admin/domain/orders/${data.order.orderId}/reconcile-provider-charge`, { method: "POST" });
      clearDomainResource("/v1/admin/domain/"); resource.reload();
      setFinancialMessage("Provider charge check completed.");
    } catch (error) {
      setFinancialMessage(error instanceof Error ? error.message : "The provider charge could not be checked.");
    } finally { setFinancialPending(false); }
  };
  const financialStatus = String(data.order.financialStatus || "NOT_STARTED");
  return <div className="space-y-6">
    <Button asChild variant="ghost"><Link href="/admin/orders">← Back to orders</Link></Button>
    <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="text-2xl font-semibold">Order for {data.order.domainName}</h2><p className="text-sm text-muted-foreground">Order ID: {data.order.orderId}</p></div>{data.order.status === "COMPLETED" && ["NOT_STARTED", "PENDING", "MISMATCH", "NEEDS_REVIEW"].includes(financialStatus) && <Button type="button" variant="outline" disabled={financialPending} onClick={() => void reconcileFinancialCharge()}><RefreshCcw className={financialPending ? "animate-spin" : ""} />Check Provider Charge</Button>}</div>
    {financialMessage && <p className="rounded-md border p-3 text-sm">{financialMessage}</p>}
    <Card><CardHeader><CardTitle>Order and vendor information</CardTitle></CardHeader><CardContent className="grid gap-5 md:grid-cols-3"><div><p className="text-xs text-muted-foreground">Vendor</p><VendorIdentity item={data.order} /></div>{[["Operation", data.order.operation], ["Order status", data.order.status.replaceAll("_", " ")], ["Purchased period", `${data.order.period} year(s)`], ["Created", formatDomainDate(data.order.createdAt)], ["Completed", formatDomainDate(data.order.completedAt)], ["Expires", formatDomainDate(data.order.expirationDate)]].map(([label, value]) => <div key={label}><p className="text-xs text-muted-foreground">{label}</p><p className="font-medium">{value}</p></div>)}</CardContent></Card>
    <Card><CardHeader><CardTitle>Pricing and provider charge</CardTitle><CardDescription>Estimated values use the purchase-time quote. Confirmed values come from the matched provider transaction.</CardDescription></CardHeader><CardContent className="grid gap-5 md:grid-cols-4">{[
      ["Vendor price", formatDomainAmount(data.order.amount, data.order.currency)], ["Credits charged", data.order.credits],
      ["Estimated provider cost", formatDomainAmount(data.order.pricingSnapshot?.providerCostCustomerCurrency, data.order.currency)], ["Estimated profit", formatDomainAmount(data.order.pricingSnapshot?.marginAmount, data.order.currency)],
      ["Confirmed provider charge", data.order.providerChargeCustomerAmount == null ? "Waiting for confirmation" : formatDomainAmount(data.order.providerChargeCustomerAmount, data.order.currency)],
      ["Provider refund", formatDomainAmount(data.order.providerRefundCustomerAmount || 0, data.order.currency)],
      ["Confirmed net provider cost", data.order.providerNetCostCustomerAmount == null ? "Waiting for confirmation" : formatDomainAmount(data.order.providerNetCostCustomerAmount, data.order.currency)],
      ["Confirmed profit", data.order.confirmedProfitAmount == null ? "Waiting for confirmation" : formatDomainAmount(data.order.confirmedProfitAmount, data.order.currency)],
      ["Charge status", financialStatus.replaceAll("_", " ")], ["Provider transaction", data.order.providerTransactionId || "Waiting for confirmation"],
      ["Confirmed at", formatDomainDate(data.order.providerChargeConfirmedAt)], ["Review note", data.order.financialReviewReason || "No review needed"],
    ].map(([label, value]) => <div key={String(label)}><p className="text-xs text-muted-foreground">{label}</p><p className="break-all font-medium">{value}</p></div>)}</CardContent></Card>
    <RegistrationDetails details={data.registrationDetails} /><SimpleRows title="Credit activity" items={data.ledger} keyName="_id" /><SimpleRows title="Related activity" items={data.activity} keyName="_id" />
  </div>;
}

function DataPage<T>({ title, description, resource, controls, children }: { title: string; description: string; resource: { data: T | null; loading: boolean; error: string; reload: () => void }; controls?: ReactNode; children: ReactNode }) { return <div className="space-y-6"><div className="flex items-end justify-between"><div><h2 className="text-2xl font-semibold">{title}</h2><p className="text-sm text-muted-foreground">{description}</p></div><div className="flex gap-2">{controls}<Button variant="outline" size="icon" onClick={resource.reload}><RefreshCcw /></Button></div></div>{resource.error ? <PageError message={resource.error} retry={resource.reload} /> : resource.loading ? <Loading /> : <Card><CardContent className="space-y-4 overflow-x-auto py-6">{children}</CardContent></Card>}</div>; }

function LedgerPage({ token }: { token: string }) {
  const [page, setPage] = useState(1); const [status, setStatus] = useState(""); const resource = useDomainResource<PageResult<LedgerRow>>(token, `/v1/admin/domain/wallet-ledger?page=${page}&limit=25${status ? `&status=${status}` : ""}`, 10_000);
  return <DataPage title="Credit activity" description="Track credits reserved, charged or returned for every domain order." resource={resource} controls={<select className="h-9 rounded-md border bg-background px-3 text-sm" value={status} onChange={(e) => { setPage(1); setStatus(e.target.value); }}><option value="">All entries</option>{["RESERVED", "SETTLING", "RELEASING", "SETTLED", "RELEASED"].map((v) => <option key={v}>{v}</option>)}</select>}><table className="w-full min-w-5xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Order</th><th>Vendor</th><th>Type</th><th>Credits</th><th>Balance after</th><th>Status</th><th>Date</th></tr></thead><tbody>{resource.data?.items.map((item) => <tr key={item._id} className="border-b"><td className="py-4"><Link className="hover:underline" href={`/admin/orders/${item.orderId}`}>{item.orderId}</Link></td><td><VendorIdentity item={item} /></td><td>{item.operation}</td><td>{item.credits}</td><td>{item.balanceAfter}</td><td><Badge variant="outline">{item.status}</Badge></td><td>{formatDomainDate(item.createdAt)}</td></tr>)}</tbody></table>{!resource.data?.items.length ? <Empty>No credit activity found.</Empty> : resource.data && <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}</DataPage>;
}

function ActivityPage({ token, searches = false }: { token: string; searches?: boolean }) {
  const [page, setPage] = useState(1); const [outcome, setOutcome] = useState(""); const base = searches ? "/v1/admin/domain/activity/searches" : "/v1/admin/domain/activity/audit"; const resource = useDomainResource<PageResult<AuditRow>>(token, `${base}?page=${page}&limit=25${outcome ? `&outcome=${outcome}` : ""}`, 10_000);
  const vendor = (item: AuditRow) => <div><p className="font-medium">{item.vendorName || "Vendor"}</p><p className="text-xs text-muted-foreground">{item.vendorEmail || "Email not available"}</p></div>;
  return <DataPage title={searches ? "Search activity" : "Audit log"} description={searches ? "See what vendors searched for and whether each search completed." : "Review purchases, pricing changes, catalogue updates and other important actions. Domain searches are shown separately."} resource={resource} controls={<select className="h-9 rounded-md border bg-background px-3 text-sm" value={outcome} onChange={(e) => { setPage(1); setOutcome(e.target.value); }}><option value="">All results</option>{["SUCCESS", "FAILURE", "UNKNOWN"].map((v) => <option key={v}>{v}</option>)}</select>}>
    {searches ? <table className="w-full min-w-4xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Searched domain</th><th>Vendor</th><th>Search type</th><th>Result</th><th>Searched at</th></tr></thead><tbody>{resource.data?.items.map((item) => <tr key={item._id} className="border-b"><td className="py-4 font-medium">{item.domainName || "Multiple domains"}</td><td>{vendor(item)}</td><td>{item.action === "DOMAIN_BULK_SEARCH" ? "Multiple domain search" : "Single domain search"}</td><td><Badge variant="outline">{item.outcome}</Badge></td><td>{formatDomainDate(item.createdAt)}</td></tr>)}</tbody></table>
      : <table className="w-full min-w-5xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Action</th><th>Domain</th><th>Vendor</th><th>Performed by</th><th>Result</th><th>Date</th></tr></thead><tbody>{resource.data?.items.map((item) => <tr key={item._id} className="border-b"><td className="py-4">{item.action.replaceAll("_", " ")}</td><td>{item.domainName || "Not applicable"}</td><td>{vendor(item)}</td><td className="capitalize">{item.actorRole}</td><td><Badge variant="outline">{item.outcome}</Badge></td><td>{formatDomainDate(item.createdAt)}</td></tr>)}</tbody></table>}
    {!resource.data?.items.length ? <Empty>{searches ? "No domain searches found." : "No important actions have been recorded yet."}</Empty> : resource.data && <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}
  </DataPage>;
}

function CataloguePage({ token }: { token: string }) {
  const [page, setPage] = useState(1); const [pending, setPending] = useState(false); const [message, setMessage] = useState(""); const resource = useDomainResource<PageResult<{ tld: string; lastSyncedAt?: string }>>(token, `/v1/admin/domain/catalogue?page=${page}&limit=25`, 30_000);
  const refresh = async () => { setPending(true); setMessage(""); try { await domainApi(token, "/v1/admin/domain/catalogue/refresh", { method: "POST" }); clearDomainResource("/v1/admin/domain/"); resource.reload(); setMessage("Domain catalogue refreshed successfully."); } catch (error) { setMessage(error instanceof Error ? error.message : "Catalogue refresh could not be completed."); } finally { setPending(false); } };
  return <div className="space-y-6"><div className="flex items-end justify-between"><div><h2 className="text-2xl font-semibold">Domain catalogue</h2><p className="text-sm text-muted-foreground">Review available extensions and refresh provider pricing when needed.</p></div><Button disabled={pending} onClick={() => void refresh()}><RefreshCcw />{pending ? "Refreshing..." : "Refresh catalogue"}</Button></div>{message && <p className="rounded-md border p-3 text-sm">{message}</p>}{resource.error ? <PageError message={resource.error} retry={resource.reload} /> : resource.loading ? <Loading /> : <Card><CardContent className="space-y-4 py-6"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{resource.data?.items.map((item) => <div key={item.tld} className="rounded-md border p-4"><p className="font-semibold">.{item.tld}</p><p className="text-xs text-muted-foreground">Updated {formatDomainDate(item.lastSyncedAt)}</p></div>)}</div>{!resource.data?.items.length ? <Empty>No catalogue entries found.</Empty> : resource.data && <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}</CardContent></Card>}</div>;
}

function SimpleBreakdown({ title, rows }: { title: string; rows: Array<{ label: string; value: number; detail?: string }> }) { return <Card><CardHeader><CardTitle>{title}</CardTitle></CardHeader><CardContent>{rows.map((row) => <div key={row.label} className="flex justify-between border-b py-3 text-sm"><span>{row.label}</span><span className="font-medium">{row.value}{row.detail ? ` · ${row.detail}` : ""}</span></div>)}{!rows.length && <Empty>No data in this range.</Empty>}</CardContent></Card>; }

function ReportsPage({ token }: { token: string }) {
  const pathname = usePathname();
  const dateValue = (date: Date) => new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Kolkata", year: "numeric", month: "2-digit", day: "2-digit" }).format(date);
  const initial = useMemo<{ from: string; to: string; groupBy: "day" | "month" | "year" }>(() => { const to = new Date(); const from = new Date(to.getTime() - 29 * 86_400_000); return { from: dateValue(from), to: dateValue(to), groupBy: "day" }; }, []);
  const [inputs, setInputs] = useState(initial);
  const [range, setRange] = useState(initial);
  const [providerPage, setProviderPage] = useState(1);
  const [providerStatus, setProviderStatus] = useState("");
  const [providerFilter, setProviderFilter] = useState("");
  const [issuePage, setIssuePage] = useState(1);
  const [issueStatus, setIssueStatus] = useState("");
  const [issueOperation, setIssueOperation] = useState("");
  const [issueFilter, setIssueFilter] = useState("");
  const resource = useDomainResource<Report>(token, `/v1/admin/domain/reports?from=${range.from}&to=${range.to}&groupBy=${range.groupBy}`, 30_000);
  const providerCharges = useDomainResource<PageResult<ProviderChargeRow>>(token, pathname.endsWith("provider-charges") ? `/v1/admin/domain/provider/charges?page=${providerPage}&limit=25&from=${range.from}&to=${range.to}&filter=${encodeURIComponent(providerFilter)}${providerStatus ? `&status=${providerStatus}` : ""}` : "", 10_000);
  const orderIssues = useDomainResource<PageResult<OrderIssueRow>>(token, pathname.endsWith("order-issues") ? `/v1/admin/domain/reports/order-issues?page=${issuePage}&limit=25&from=${range.from}&to=${range.to}&filter=${encodeURIComponent(issueFilter)}${issueStatus ? `&status=${issueStatus}` : ""}${issueOperation ? `&operation=${issueOperation}` : ""}` : "", 10_000);
  const money = (value: number | null) => value == null ? "Not confirmed" : formatDomainAmount(value, resource.data?.summary.currency || "INR");
  const confirmedProfit = (row: FinancialRow) => row.confirmedProfit == null ? "Not confirmed" : formatDomainAmount(row.confirmedProfit, resource.data?.summary.currency || "INR");
  const preset = (kind: "today" | "7days" | "30days" | "month" | "year") => {
    const now = new Date(); let from = new Date(now); let groupBy: "day" | "month" | "year" = "day";
    if (kind === "7days") from = new Date(now.getTime() - 6 * 86_400_000);
    if (kind === "30days") from = new Date(now.getTime() - 29 * 86_400_000);
    if (kind === "month") from = new Date(now.getFullYear(), now.getMonth(), 1);
    if (kind === "year") { from = new Date(now.getFullYear(), 0, 1); groupBy = "month"; }
    const value = { from: dateValue(from), to: dateValue(now), groupBy }; setInputs(value); setRange(value);
  };
  const csvRows = () => {
    if (!resource.data) return [];
    if (pathname.endsWith("domain-performance")) return [["Domain type", "Completed orders", "Vendor charges", "Confirmed net provider cost", "Confirmed profit"], ...resource.data.domainTypes.map((row) => [`.${row.tld}`, row.count, row.revenue, row.confirmedProviderCost ?? "Not confirmed", row.confirmedProfit ?? "Not confirmed"])];
    if (pathname.endsWith("vendor-performance")) return [["Vendor", "Email", "Completed orders", "Registrations", "Renewals", "Vendor charges", "Confirmed net provider cost", "Confirmed profit"], ...resource.data.vendors.map((row) => [row.vendorName, row.vendorEmail, row.count, row.registrations, row.renewals, row.revenue, row.confirmedProviderCost ?? "Not confirmed", row.confirmedProfit ?? "Not confirmed"] )];
    if (pathname.endsWith("provider-charges")) return [["Order", "Domain", "Vendor", "Vendor charge", "Estimated provider cost", "Confirmed provider charge", "Refund", "Net provider cost", "Confirmed profit", "Status", "Trace ID"], ...(providerCharges.data?.items || []).map((row) => [row.orderId, row.domainName, row.vendorName, row.vendorCharge, row.estimatedProviderCost ?? "Not available", row.confirmedProviderCharge ?? "Not confirmed", row.providerRefund, row.netProviderCost ?? "Not confirmed", row.confirmedProfit ?? "Not confirmed", row.financialStatus, row.traceId])];
    if (pathname.endsWith("order-issues")) return [["Order", "Domain", "Vendor", "Status", "Created"], ...(orderIssues.data?.items || []).map((row) => [row.orderId, row.domainName, row.vendorName, row.status, row.createdAt])];
    return [["Period", "Completed", "Registrations", "Renewals", "Vendor charges", "Confirmed net provider cost", "Confirmed profit"], ...resource.data.trend.map((row) => [row.period, row.count, row.registrations, row.renewals, row.revenue, row.confirmedProviderCost ?? "Not confirmed", row.confirmedProfit ?? "Not confirmed"])];
  };
  const download = async () => {
    let rows = csvRows();
    if (pathname.endsWith("provider-charges") && providerCharges.data?.total) {
      const all: ProviderChargeRow[] = [];
      const pages = Math.ceil(providerCharges.data.total / 100);
      for (let pageNumber = 1; pageNumber <= pages; pageNumber += 1) {
        const result = await domainApi<PageResult<ProviderChargeRow>>(token, `/v1/admin/domain/provider/charges?page=${pageNumber}&limit=100&from=${range.from}&to=${range.to}&filter=${encodeURIComponent(providerFilter)}${providerStatus ? `&status=${providerStatus}` : ""}`);
        all.push(...result.items);
      }
      rows = [["Order", "Domain", "Vendor", "Vendor email", "Vendor charge", "Estimated provider cost", "Original provider charge", "Provider currency", "Confirmed INR charge", "Refund", "Net provider cost", "Confirmed profit", "Status", "Trace ID"], ...all.map((row) => [row.orderId, row.domainName, row.vendorName, row.vendorEmail, row.vendorCharge, row.estimatedProviderCost ?? "Not available", row.originalProviderCharge ?? "Not confirmed", row.originalProviderChargeCurrency, row.confirmedProviderCharge ?? "Not confirmed", row.providerRefund, row.netProviderCost ?? "Not confirmed", row.confirmedProfit ?? "Not confirmed", row.financialStatus, row.traceId])];
    }
    if (pathname.endsWith("order-issues") && orderIssues.data?.total) {
      const all: OrderIssueRow[] = [];
      const pages = Math.ceil(orderIssues.data.total / 100);
      for (let pageNumber = 1; pageNumber <= pages; pageNumber += 1) {
        const result = await domainApi<PageResult<OrderIssueRow>>(token, `/v1/admin/domain/reports/order-issues?page=${pageNumber}&limit=100&from=${range.from}&to=${range.to}&filter=${encodeURIComponent(issueFilter)}${issueStatus ? `&status=${issueStatus}` : ""}${issueOperation ? `&operation=${issueOperation}` : ""}`);
        all.push(...result.items);
      }
      rows = [["Order", "Domain", "Vendor", "Vendor email", "Type", "Status", "Amount", "Created", "Reason"], ...all.map((row) => [row.orderId, row.domainName, row.vendorName || "Vendor", row.vendorEmail || "", row.operation, row.status, row.amount, row.createdAt, row.failureMessage || row.financialReviewReason || "Awaiting completion"])];
    }
    if (!rows.length) return;
    const csv = rows.map((row) => row.map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = `domain-report-${range.from}-${range.to}.csv`; link.click(); URL.revokeObjectURL(url);
  };
  const page = pathname.endsWith("sales-profit") ? "sales" : pathname.endsWith("domain-performance") ? "domains" : pathname.endsWith("vendor-performance") ? "vendors" : pathname.endsWith("provider-charges") ? "provider" : pathname.endsWith("order-issues") ? "issues" : "summary";
  const headings = { summary: ["Report summary", "Completed domain business for the selected period."], sales: ["Sales & profit", "Day, month or year-wise completed sales and profit."], domains: ["Domain performance", "Compare sales and profit by domain extension."], vendors: ["Vendor performance", "Compare completed business generated by each vendor."], provider: ["Provider charges", "Compare estimated provider cost with confirmed actual charges."], issues: ["Failed & pending orders", "Orders that are incomplete, failed or need attention."] } as const;
  if (resource.error) return <PageError message={resource.error} retry={resource.reload} />;
  const data = resource.data;
  return <div className="space-y-6">
    <div className="space-y-4"><div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><h2 className="text-2xl font-semibold">{headings[page][0]}</h2><p className="text-sm text-muted-foreground">{headings[page][1]}</p></div><form className="flex flex-wrap gap-2" onSubmit={(event) => { event.preventDefault(); setProviderPage(1); setIssuePage(1); setRange(inputs); }}><Input className="w-auto" type="date" value={inputs.from} onChange={(event) => setInputs({ ...inputs, from: event.target.value })} /><Input className="w-auto" type="date" value={inputs.to} onChange={(event) => setInputs({ ...inputs, to: event.target.value })} /><select className="h-9 rounded-md border bg-background px-3 text-sm" value={inputs.groupBy} onChange={(event) => setInputs({ ...inputs, groupBy: event.target.value as "day" | "month" | "year" })}><option value="day">Day-wise</option><option value="month">Month-wise</option><option value="year">Year-wise</option></select><Button>Apply</Button><Button type="button" variant="outline" disabled={!data} onClick={() => void download()}><Download />CSV</Button></form></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => preset("today")}>Today</Button><Button size="sm" variant="outline" onClick={() => preset("7days")}>Last 7 days</Button><Button size="sm" variant="outline" onClick={() => preset("30days")}>Last 30 days</Button><Button size="sm" variant="outline" onClick={() => preset("month")}>This month</Button><Button size="sm" variant="outline" onClick={() => preset("year")}>This year</Button></div></div>
    {resource.loading ? <Loading /> : data && <>
      {page === "summary" && <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Domains sold", data.summary.registrations], ["Renewals completed", data.summary.renewals], ["Vendor charges", money(data.summary.revenue)], ["Confirmed profit", money(data.summary.confirmedProfit)]].map(([label, value]) => <Card key={label}><CardHeader><CardDescription>{label}</CardDescription><CardTitle>{value}</CardTitle></CardHeader></Card>)}</section><section className="grid gap-6 lg:grid-cols-2"><SimpleBreakdown title="Completed orders" rows={data.operations.map((row) => ({ label: row.operation.replaceAll("_", " "), value: row.count, detail: formatDomainAmount(row.revenue, data.summary.currency) }))} /><SimpleBreakdown title="Orders needing attention" rows={data.statuses.filter((row) => row.status !== "COMPLETED").map((row) => ({ label: row.status.replaceAll("_", " "), value: row.count }))} /></section></>}
      {page === "sales" && <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Completed sales", data.summary.completedOrders], ["Vendor charges", money(data.summary.revenue)], ["Confirmed net provider cost", money(data.summary.netProviderCost)], ["Confirmed profit", money(data.summary.confirmedProfit)]].map(([label, value]) => <Card key={label}><CardHeader><CardDescription>{label}</CardDescription><CardTitle>{value}</CardTitle></CardHeader></Card>)}</section><Card><CardHeader><CardTitle>{range.groupBy === "day" ? "Day-wise" : range.groupBy === "month" ? "Month-wise" : "Year-wise"} results</CardTitle><CardDescription>Confirmed amounts appear only when every completed order in that row has a matched provider charge.</CardDescription></CardHeader><CardContent className="overflow-x-auto"><table className="w-full min-w-4xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Period</th><th>Sales</th><th>Registrations</th><th>Renewals</th><th>Vendor charges</th><th>Confirmed net provider cost</th><th>Confirmed profit</th></tr></thead><tbody>{data.trend.map((row) => <tr key={row.period} className="border-b"><td className="py-4 font-medium">{row.period}</td><td>{row.count}</td><td>{row.registrations}</td><td>{row.renewals}</td><td>{money(row.revenue)}</td><td>{row.confirmedProviderCost == null ? "Not confirmed" : money(row.confirmedProviderCost)}</td><td>{confirmedProfit(row)}</td></tr>)}</tbody></table>{!data.trend.length && <Empty>No completed sales in this period.</Empty>}</CardContent></Card></>}
      {page === "domains" && <ReportTable headers={["Domain type", "Completed orders", "Vendor charges", "Confirmed net provider cost", "Confirmed profit"]} rows={data.domainTypes.map((row) => [`.${row.tld}`, row.count, money(row.revenue), row.confirmedProviderCost == null ? "Not confirmed" : money(row.confirmedProviderCost), confirmedProfit(row)])} empty="No completed domain sales in this period." />}
      {page === "vendors" && <ReportTable headers={["Vendor", "Completed orders", "Registrations", "Renewals", "Vendor charges", "Confirmed net provider cost", "Confirmed profit", "Last sale"]} rows={data.vendors.map((row) => [<div key={row.vendorId}><p className="font-medium">{row.vendorName}</p><p className="text-xs text-muted-foreground">{row.vendorEmail}</p></div>, row.count, row.registrations, row.renewals, money(row.revenue), row.confirmedProviderCost == null ? "Not confirmed" : money(row.confirmedProviderCost), confirmedProfit(row), formatDomainDate(row.lastCompletedAt)])} empty="No completed vendor sales in this period." />}
      {page === "provider" && <>
        <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{[["Estimated provider cost", money(data.summary.estimatedProviderCost)], ["Confirmed provider charge", money(data.summary.actualProviderCharge)], ["Confirmed refunds", money(data.summary.providerRefunds)], ["Net provider cost", money(data.summary.netProviderCost)], ["Confirmed profit", money(data.summary.confirmedProfit)]].map(([label, value]) => <Card key={label}><CardHeader><CardDescription>{label}</CardDescription><CardTitle>{value}</CardTitle></CardHeader></Card>)}</section>
        <Card><CardHeader><CardTitle>Find a provider charge</CardTitle><CardDescription>Search confirmed, pending, refunded or review-required financial records.</CardDescription></CardHeader><CardContent className="grid gap-3 sm:grid-cols-2"><Input value={providerFilter} onChange={(event) => { setProviderFilter(event.target.value); setProviderPage(1); }} placeholder="Search domain, order or trace ID" /><select className="h-9 rounded-md border bg-background px-3 text-sm" value={providerStatus} onChange={(event) => { setProviderStatus(event.target.value); setProviderPage(1); }}><option value="">All confirmation statuses</option>{["NOT_STARTED", "PENDING", "CONFIRMED", "PARTIALLY_REFUNDED", "REFUNDED", "MISMATCH", "NEEDS_REVIEW"].map((value) => <option key={value} value={value}>{value.replaceAll("_", " ")}</option>)}</select></CardContent></Card>
        {providerCharges.error ? <PageError message={providerCharges.error} retry={providerCharges.reload} /> : providerCharges.loading ? <Loading /> : <Card><CardHeader><CardTitle>Order-level provider charges</CardTitle><CardDescription>Amounts are confirmed from the provider ledger. Unknown values are never treated as zero.</CardDescription></CardHeader><CardContent className="space-y-4 overflow-x-auto"><table className="w-full min-w-7xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Domain</th><th>Vendor</th><th>Type</th><th>Vendor charge</th><th>Estimated cost</th><th>Original provider charge</th><th>Confirmed INR charge</th><th>Refund</th><th>Net cost</th><th>Profit</th><th>Status</th><th>Trace ID</th></tr></thead><tbody>{providerCharges.data?.items.map((row) => <tr key={row.orderId} className="border-b"><td className="py-4"><Link className="font-medium hover:underline" href={`/admin/orders/${row.orderId}`}>{row.domainName}</Link></td><td><p className="font-medium">{row.vendorName}</p><p className="text-xs text-muted-foreground">{row.vendorEmail}</p></td><td>{row.operation}</td><td>{formatDomainAmount(row.vendorCharge, row.currency)}</td><td>{row.estimatedProviderCost == null ? "Not available" : formatDomainAmount(row.estimatedProviderCost, row.currency)}</td><td>{row.originalProviderCharge == null || !row.originalProviderChargeCurrency ? "Not confirmed" : formatDomainAmount(row.originalProviderCharge, row.originalProviderChargeCurrency)}</td><td>{row.confirmedProviderCharge == null ? "Not confirmed" : formatDomainAmount(row.confirmedProviderCharge, row.currency)}</td><td>{formatDomainAmount(row.providerRefund, row.currency)}</td><td>{row.netProviderCost == null ? "Not confirmed" : formatDomainAmount(row.netProviderCost, row.currency)}</td><td>{row.confirmedProfit == null ? "Not confirmed" : formatDomainAmount(row.confirmedProfit, row.currency)}</td><td><Badge variant="outline">{row.financialStatus.replaceAll("_", " ")}</Badge>{row.reviewReason && <p className="mt-1 max-w-48 text-xs text-muted-foreground">{row.reviewReason}</p>}</td><td className="max-w-40 break-all text-xs">{row.traceId || "Waiting"}</td></tr>)}</tbody></table>{!providerCharges.data?.items.length && <Empty>No provider charge records match these filters.</Empty>}{providerCharges.data && <Pager page={providerPage} pages={providerCharges.data.pages} total={providerCharges.data.total} setPage={setProviderPage} />}</CardContent></Card>}
      </>}
      {page === "issues" && <><Card><CardHeader><CardTitle>Find an incomplete order</CardTitle><CardDescription>Search and filter without loading every order at once.</CardDescription></CardHeader><CardContent className="grid gap-3 md:grid-cols-3"><Input value={issueFilter} onChange={(event) => { setIssueFilter(event.target.value); setIssuePage(1); }} placeholder="Search domain, order or vendor" /><select className="h-9 rounded-md border bg-background px-3 text-sm" value={issueOperation} onChange={(event) => { setIssueOperation(event.target.value); setIssuePage(1); }}><option value="">All operations</option>{["REGISTER", "RENEW", "TRANSFER", "RESTORE"].map((value) => <option key={value}>{value}</option>)}</select><select className="h-9 rounded-md border bg-background px-3 text-sm" value={issueStatus} onChange={(event) => { setIssueStatus(event.target.value); setIssuePage(1); }}><option value="">All incomplete statuses</option>{["CREATED", "RESERVING", "RESERVED", "PROVIDER_PENDING", "FAILED", "RECONCILIATION_REQUIRED"].map((value) => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select></CardContent></Card>{orderIssues.error ? <PageError message={orderIssues.error} retry={orderIssues.reload} /> : orderIssues.loading ? <Loading /> : <Card><CardContent className="space-y-4 overflow-x-auto py-6"><table className="w-full min-w-5xl text-sm"><thead><tr className="border-b text-left"><th className="pb-3">Domain</th><th>Vendor</th><th>Type</th><th>Status</th><th>Amount</th><th>Created</th><th>Reason</th></tr></thead><tbody>{orderIssues.data?.items.map((row) => <tr key={row.orderId} className="border-b"><td className="py-4"><Link className="font-medium hover:underline" href={`/admin/orders/${row.orderId}`}>{row.domainName}</Link></td><td><VendorIdentity item={row} /></td><td>{row.operation}</td><td><Badge variant="outline">{row.status.replaceAll("_", " ")}</Badge></td><td>{formatDomainAmount(row.amount, row.currency)}</td><td>{formatDomainDate(row.createdAt)}</td><td>{row.failureMessage || row.financialReviewReason || "Awaiting completion"}</td></tr>)}</tbody></table>{!orderIssues.data?.items.length && <Empty>No failed or pending orders in this period.</Empty>}{orderIssues.data && <Pager page={issuePage} pages={orderIssues.data.pages} total={orderIssues.data.total} setPage={setIssuePage} />}</CardContent></Card>}</>}
    </>}
  </div>;
}

function ReportTable({ headers, rows, empty }: { headers: string[]; rows: ReactNode[][]; empty: string }) {
  return <Card><CardContent className="overflow-x-auto py-6"><table className="w-full min-w-4xl text-sm"><thead><tr className="border-b text-left">{headers.map((header) => <th key={header} className="pb-3">{header}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index} className="border-b">{row.map((cell, cellIndex) => <td key={cellIndex} className="py-4 pr-4">{cell}</td>)}</tr>)}</tbody></table>{!rows.length && <Empty>{empty}</Empty>}</CardContent></Card>;
}


function NotificationsPage({ token }: { token: string }) { const [page, setPage] = useState(1); const [unreadOnly, setUnreadOnly] = useState(false); const [updating, setUpdating] = useState(false); const resource = useDomainResource<PageResult<AdminNotification> & { unread: number }>(token, `/v1/admin/domain/notifications?page=${page}&limit=25&unreadOnly=${unreadOnly}`, 10_000); const mark = async (id: string) => { setUpdating(true); try { await domainApi(token, `/v1/admin/domain/notifications/${id}/read`, { method: "PUT" }); const unread = Math.max(0, Number(resource.data?.unread || 0) - 1); window.dispatchEvent(new CustomEvent("domain-admin-notifications-changed", { detail: { unread } })); clearDomainResource("/v1/admin/domain/notifications"); resource.reload(); } finally { setUpdating(false); } }; const markAll = async () => { setUpdating(true); try { await domainApi(token, "/v1/admin/domain/notifications/read-all", { method: "PUT" }); window.dispatchEvent(new CustomEvent("domain-admin-notifications-changed", { detail: { unread: 0 } })); clearDomainResource("/v1/admin/domain/notifications"); resource.reload(); } finally { setUpdating(false); } }; return <DataPage title="Notifications" description="Provider balance, financial reconciliation, refunds and important domain operations." resource={resource} controls={<><Button type="button" variant="outline" disabled={updating} onClick={() => { setPage(1); setUnreadOnly((value) => !value); }}>{unreadOnly ? "Show All" : "Show Unread"}</Button><Button type="button" disabled={updating || !resource.data?.unread} onClick={() => void markAll()}>Mark All as Read</Button></>}><div className="space-y-3">{resource.data?.items.map((item) => <div key={item._id} className={`rounded-md border p-4 ${item.readAt ? "" : "bg-primary/5"}`}><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="font-medium">{item.title}</p><Badge variant="outline">{item.severity}</Badge>{!item.readAt && <Badge>New</Badge>}</div><p className="mt-1 text-sm text-muted-foreground">{item.message}</p><p className="mt-2 text-xs text-muted-foreground">{formatDomainDate(item.createdAt)}</p></div><div className="flex gap-2">{item.orderId && <Button asChild size="sm" variant="outline"><Link href={`/admin/orders/${item.orderId}`}>Open Order</Link></Button>}{!item.readAt && <Button type="button" size="sm" disabled={updating} onClick={() => void mark(item._id)}>Mark Read</Button>}</div></div></div>)}{!resource.data?.items.length && <Empty>You are all caught up.</Empty>}{resource.data && <Pager page={page} pages={resource.data.pages} total={resource.data.total} setPage={setPage} />}</div></DataPage>; }

export function AdminSectionPage({ section, token }: { section: AdminSection; token: string }) { const pathname = usePathname(); const parts = pathname.split("/").filter(Boolean); if (parts[1] === "vendors" && parts[2]) return <DetailPage token={token} kind="vendors" id={decodeURIComponent(parts[2])} />; if (parts[1] === "domains" && parts[2]) return <DetailPage token={token} kind="domains" id={decodeURIComponent(parts[2])} />; if (parts[1] === "orders" && parts[2]) return <DetailPage token={token} kind="orders" id={decodeURIComponent(parts[2])} />; if (pathname === "/admin/operations/wallet-ledger") return <LedgerPage token={token} />; if (pathname === "/admin/operations/provider-transactions") return <ProviderTransactionsPage token={token} />; if (pathname === "/admin/operations/search-activity") return <ActivityPage token={token} searches />; if (pathname === "/admin/operations/audit-logs") return <ActivityPage token={token} />; if (pathname === "/admin/operations/catalogue") return <CataloguePage token={token} />; if (section === "Vendors") return <VendorsPage token={token} />; if (section === "Domains") return <DomainsPage token={token} />; if (section === "Orders") return <OrdersPage token={token} />; if (section === "Pricing") return <AdminPricingPage token={token} />; if (section === "Reports") return <ReportsPage token={token} />; if (section === "Settings") return <AdminSettingsPage token={token} />; if (section === "Notifications") return <NotificationsPage token={token} />; return <CataloguePage token={token} />; }
